def verify_checksum(path):
    digest = hashlib.md5()
    with open(path, 'rb') as handle:
        for block in iter(lambda: handle.read(8 * 1024 * 1024), b''):
            digest.update(block)
    actual = digest.hexdigest()
    if actual != CAD_MD5:
        raise ValueError(f'CAD checksum mismatch: {actual}')
    return actual

permutation_rows = []
for trait, frame in trait_frames.items():
    if trait in PSYCHIATRIC_GWAS:
        saved_summary = psychiatric_summaries[trait]
    else:
        filename = 'summary.json' if trait == 'OCD' else 'cad_summary.json'
        saved_summary = json.loads((OUT / filename).read_text())
    for window, width, suffix in WINDOWS:
        recalculate = (RUN_PERMUTATIONS or REBUILD_WINDOWS or
            trait in rebuilt_psychiatric or
            window not in saved_summary.get('windows', {}))
        if recalculate:
            print(f'{trait} {window}: running 10,000 circular shifts', flush=True)
            _, tests = rank_and_permute(frame, n=10_000,
                p_col=f'min_p{suffix}', count_col=f'n_snps{suffix}')
        else:
            tests = saved_summary['windows'][window]['tests']
        if trait in PSYCHIATRIC_GWAS:
            covered = frame[f'n_snps{suffix}'].gt(0)
            saved_summary['windows'][window] = {
                'width_each_side_bp': width, 'genes_covered': int(covered.sum()),
                'dog_covered': int((covered & frame.dog).sum()), 'tests': tests}
        for dog_set, test in tests.items():
            permutation_rows.append({'Trait': trait, 'Window': WINDOW_LABELS[window],
                'Dog set': 'combined' if dog_set == 'all' else dog_set,
                'Dog genes': test['n'], 'Mean rank': test['observed_mean_rank'],
                'Null mean rank': test['null_mean'],
                'Empirical p': test['empirical_one_sided_p'],
                'Permutations': test['permutations']})
    if trait in PSYCHIATRIC_GWAS:
        (NOTEBOOK_OUT / f'{trait.lower()}_summary.json').write_text(
            json.dumps(saved_summary, indent=2))
permutation_results = pd.DataFrame(permutation_rows)
permutation_results.to_csv(NOTEBOOK_OUT / 'circular_shift_results.csv', index=False)


def display_permutations(traits):
    table = permutation_results.loc[permutation_results.Trait.isin(traits)]
    display(table.style.format({'Mean rank': '{:.4f}',
        'Null mean rank': '{:.4f}', 'Empirical p': '{:.3g}'}).hide(axis='index'))


